1	import { parseScenario, runScenario } from "./claim-office.js";
2	
3	const readStdin = (): Promise<string> =>
4	  new Promise((resolve) => {
5	    let input = "";
6	
7	    process.stdin.on("data", (chunk) => (input += chunk));
8	    process.stdin.on("end", () => resolve(input));
9	  });
10	
11	// The only write to stdout. A failure throws before reaching it, which is what
12	// keeps results off stdout on the error path.
13	const reportScenarioOutcome = async (): Promise<void> => {
14	  const outcome = runScenario(parseScenario(JSON.parse(await readStdin())));
15	
16	  process.stdout.write(JSON.stringify(outcome));
17	};
18	
19	// The only write to stderr: a description, not a stack trace. The domain errors
20	// are already phrased for a human reader, so the message is passed through
21	// as-is on a single line.
22	const reportFailure = (error: unknown): void => {
23	  const description = error instanceof Error ? error.message : String(error);
24	
25	  process.stderr.write(`${description}\n`);
26	  process.exitCode = 1;
27	};
28	
29	try {
30	  await reportScenarioOutcome();
31	} catch (error) {
32	  reportFailure(error);
33	}
